@layer hj.components {
  /* Customise: --hj-accordion-row-height · --hj-accordion-gap (panel bottom spacing) */
  .hj-accordion-root {
    display: flex;
    flex-direction: column;
    min-width: 0;
    font-family: var(--hj-font-sans);
  }
  .hj-accordion-root[data-variant='lined'] {
    border-top: 1px solid var(--hj-line);
  }
  .hj-accordion-root[data-variant='lined'] .hj-accordion-item {
    border-bottom: 1px solid var(--hj-line);
  }
  .hj-accordion-header {
    margin: 0;
    font: inherit;
  }

  .hj-accordion-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--hj-space-4);
    width: 100%;
    min-height: var(--hj-accordion-row-height, calc(56px * var(--hj-density-size)));
    padding: var(--hj-space-3) 0;
    border: 0;
    background: none;
    color: var(--hj-fg);
    font: 600 15px / 1.35 var(--hj-font-sans);
    letter-spacing: -0.01em;
    text-align: left;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-accordion-trigger:hover:not([data-disabled]) .hj-accordion-chevron {
    color: var(--hj-fg);
  }
  .hj-accordion-trigger:active:not([data-disabled]) .hj-accordion-label {
    opacity: var(--hj-press-opacity);
  }
  .hj-accordion-trigger[data-disabled] {
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }
  .hj-accordion-trigger:focus-visible {
    outline-offset: -2px;
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
  }
  .hj-accordion-label {
    min-width: 0;
    transition: opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-accordion-chevron {
    display: inline-flex;
    flex: none;
    color: var(--hj-fg-mute);
    font-size: 20px;
    line-height: 0;
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-accordion-trigger[data-panel-open] .hj-accordion-chevron {
    transform: rotate(180deg);
  }

  /*
   * The one declared layout transition: the panel's height, from Base UI's measured
   * --accordion-panel-height. Clipped, clamped and short; content fades with it.
   */
  .hj-accordion-panel {
    height: var(--accordion-panel-height);
    overflow: hidden;
    color: var(--hj-fg-dim);
    font-size: 14.5px;
    line-height: 1.6;
    transition:
      height var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-accordion-panel > :first-child {
    margin-top: 0;
  }
  .hj-accordion-panel > :last-child {
    margin-bottom: var(--hj-accordion-gap, var(--hj-space-4));
  }
  .hj-accordion-panel[data-starting-style],
  .hj-accordion-panel[data-ending-style] {
    height: 0;
    opacity: 0;
  }
  .hj-accordion-panel[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
}

'use client';
import { Accordion as Base } from '@base-ui/react/accordion';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export const Item: HanjiPart<typeof Base.Item> = part(
  Base.Item,
  'Accordion.Item',
  'hj-accordion-item',
);
export const Header: HanjiPart<typeof Base.Header> = part(
  Base.Header,
  'Accordion.Header',
  'hj-accordion-header',
);
export const Panel: HanjiPart<typeof Base.Panel> = part(
  Base.Panel,
  'Accordion.Panel',
  'hj-accordion-panel',
);

export interface RootOwnProps {
  /** lined = hairlines between items (hanji) · plain = no rules, for nesting inside a surface. */
  variant?: 'lined' | 'plain';
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/** Owns which items are open (value / defaultValue / onValueChange, multiple). */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const { variant = 'lined', className, ...rest } = withDefaults(config, 'Accordion.Root', props);
  return (
    <Base.Root
      {...rest}
      data-variant={variant}
      className={cls(config, 'Accordion.Root', 'hj-accordion-root', className)}
    />
  );
}

export interface TriggerOwnProps {
  /** Draw the chevron that turns 180° when open. @default true */
  chevron?: boolean;
}
export interface TriggerProps extends TriggerOwnProps, Base.Trigger.Props {}

/** The row that opens and closes its item. Put it inside `Accordion.Header`. */
export function Trigger(props: TriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    chevron = true,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Accordion.Trigger', props);
  const styled = !config.unstyled;
  return (
    <Base.Trigger
      {...rest}
      data-chevron={flag(chevron)}
      className={cls(config, 'Accordion.Trigger', 'hj-accordion-trigger', className)}
    >
      <span className={styled ? 'hj-accordion-label' : undefined}>{children}</span>
      {chevron ? (
        <span className={styled ? 'hj-accordion-chevron' : undefined} aria-hidden="true">
          {config.icons.chevronDown}
        </span>
      ) : null}
    </Base.Trigger>
  );
}

export * as Accordion from './accordion.tsx';
export type {
  RootOwnProps as AccordionRootOwnProps,
  RootProps as AccordionRootProps,
  TriggerOwnProps as AccordionTriggerOwnProps,
  TriggerProps as AccordionTriggerProps,
} from './accordion.tsx';
